auth11={'J01':('7003',5,1),'J02':('7013',6,2),'J03':('2020',4,2),'J04':('7032',5,3),'J05':('7043',4,2),
        'J06':('7052',2,2),'J07':('7063',6,1),'J08':('7073',2,2),'J09':('2080',5,1),'J10':('7093',4,1),
        'J11':('2100',5,3),'J12':('2110',3,1)}
close3={r['案号']:int(r['实占']) for r in csv.DictReader(open('out/结班.csv',encoding='utf-8-sig'))}
vou=list(csv.DictReader(open('scratch/inbox/续办券.csv',encoding='utf-8-sig')))
cv={r['兑现案'] for r in csv.DictReader(open('inbox/06-11/注销券.csv',encoding='utf-8-sig'))}
info={}
for c,(doc,base,pri) in auth11.items():
    v=[x for x in vou if x['兑现案']==c][0]
    win=int(v['生效日'])<=11<=int(v['末日'])
    dui=0 if (c in cv or not win) else min(int(v['转入上限']),max(0,int(v['保证基数'])-close3[v['来源案']]))
    info[c]=dict(doc=doc,base=base,dui=dui,ed=base+dui,pri=pri-1 if dui>0 else pri,win=win)
pool={s:cap[s]-sum(o11[c][1] for c in o11 if st[c]==s) for s in cap}
tgt={};rem=dict(pool)
for c in sorted(info,key=lambda x:(info[x]['pri'],x)):
    need=max(0,info[c]['ed']-o11[c][1]); add=min(need,rem[st[c]]); rem[st[c]]-=add; tgt[c]=o11[c][1]+add
print('注销券',cv,'池',pool)
for c in sorted(tgt,key=lambda x:int(x[1:])):
    i=info[c]; print(c,st[c],i['doc'],'基',i['base'],'兑',i['dui'],'额',i['ed'],'优',i['pri'],'锁',o11[c][1],'净',max(0,i['ed']-o11[c][1]),'目标',tgt[c],'开班实占',o11[c][0],'差',tgt[c]-o11[c][0],'' if i['win'] else '券过期','注销' if c in cv else '')
print('Σ目标',{s:sum(tgt[c] for c in tgt if st[c]==s) for s in cap})
rows=[[c,info[c]['doc'],info[c]['base'],info[c]['dui'],info[c]['ed'],info[c]['pri'],tgt[c],o11[c][0],o11[c][3]] for c in sorted(tgt,key=lambda x:int(x[1:]))]
with open('out/调度.csv','w',encoding='utf-8',newline='') as f:
    w=csv.writer(f,lineterminator='\n'); w.writerow(['案号','批文','基础额度','兑入','额度','优先号','目标','实占','最后受理号']); w.writerows(rows)
json.dump(dict(info=info,tgt=tgt,o11=o11),open('scratch/day11_plan.json','w'),ensure_ascii=False)
print(open('out/调度.csv',encoding='utf-8').read())
PY

